pg-easy-18.syntax:
-- General form
INSERT INTO t (cols) VALUES (...) RETURNING output_expr [, ...];
UPDATE t SET col = expr WHERE cond RETURNING output_expr [AS name] [, ...];
DELETE FROM t WHERE cond RETURNING output_expr [, ...];

-- Examples (different table/columns)
INSERT INTO users (name) VALUES ('Ana') RETURNING id, name;

UPDATE items SET qty = qty - 1 WHERE sku = 'A7'
  RETURNING sku, qty AS qty_now;

DELETE FROM sessions WHERE expired_at < now()
  RETURNING token;

-- Variations and gotchas
-- * RETURNING * returns all columns of the affected rows; expressions are allowed.
-- * One result row is produced per row the statement affected.
--   If no rows match, the result set is empty.
-- * Which row version is shown depends on the command: check the
--   docs for INSERT, UPDATE and DELETE.
-- * Since PostgreSQL 18, OLD and NEW can be referenced explicitly:
--     UPDATE t SET v = v + 1 RETURNING old.v AS before, new.v AS after;
-- * Works inside CTEs to chain results:
--     WITH gone AS (DELETE FROM a WHERE x > 5 RETURNING *)
--     INSERT INTO a_archive SELECT * FROM gone;
-- * BEFORE triggers can change what is stored, which affects the returned values.

pg-easy-40.syntax:
-- General form
EXPLAIN [ ( option [, ...] ) ] statement
EXPLAIN [ ANALYZE ] [ VERBOSE ] statement

-- option examples: ANALYZE, VERBOSE, COSTS, BUFFERS, FORMAT { TEXT | JSON | XML | YAML }

-- Example 1: show the planner's chosen plan with estimates
EXPLAIN SELECT * FROM orders WHERE customer_id = 42;

-- Example 2: options in parentheses, with measured numbers
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON)
SELECT count(*) FROM invoices WHERE paid = false;

-- Notes / gotchas:
-- * Without ANALYZE, output shows the planner's estimates (cost, rows, width) only.
-- * With ANALYZE, the statement is run, and actual time, actual rows and loops are reported.
-- * Costs are in arbitrary planner units, not milliseconds.
-- * Because ANALYZE really runs the statement, INSERT/UPDATE/DELETE take effect.
--   Wrap them to discard changes:
--     BEGIN;
--     EXPLAIN ANALYZE UPDATE accounts SET balance = 0 WHERE id = 7;
--     ROLLBACK;
-- * Timing overhead can be turned off with (ANALYZE, TIMING OFF).
-- * Read plans from the innermost (most indented) node outward.

pg-easy-61.syntax:
-- General form
CREATE TYPE name AS ENUM ('label1', 'label2', ...);

-- Example: define, then use like any other type
CREATE TYPE priority AS ENUM ('low', 'medium', 'high', 'urgent');
CREATE TABLE ticket (
  id    serial PRIMARY KEY,
  level priority NOT NULL DEFAULT 'medium'
);
INSERT INTO ticket (level) VALUES ('high');

-- Comparison and ordering follow the order labels were declared
SELECT * FROM ticket WHERE level > 'low' ORDER BY level;

-- Modify an existing enum
ALTER TYPE priority ADD VALUE 'critical' AFTER 'high';
ALTER TYPE priority RENAME VALUE 'low' TO 'minor';

-- Helper functions
SELECT enum_range(NULL::priority);      -- all labels in order
SELECT enum_first(NULL::priority);

-- Gotchas
-- * Labels are case-sensitive, max 63 bytes each.
-- * An enum type is distinct: values of different enum types
--   cannot be compared directly without casting.
-- * Inserting a label not in the list raises an error.
-- * Existing labels cannot be removed with ALTER TYPE.
-- * Cast to text to use string operators: level::text LIKE 'h%'

pg-easy-90.syntax:
-- General form
INSERT INTO tbl (cols) VALUES (...) RETURNING output_expr [, ...];
UPDATE tbl SET col = expr WHERE cond RETURNING output_expr [, ...];
DELETE FROM tbl WHERE cond RETURNING output_expr [, ...];

-- Examples
UPDATE accounts SET balance = balance + 50 WHERE id = 7
  RETURNING id, balance;

DELETE FROM sessions WHERE expires_at < now()
  RETURNING user_id;

INSERT INTO items (name) VALUES ('pen') RETURNING id AS new_id;

-- Notes and gotchas
-- * RETURNING yields one result row per affected row; zero rows if none matched.
-- * Expressions can use any column of the target table, or * for all columns.
-- * For INSERT and UPDATE, plain column references see the row as stored by the
--   statement (including defaults and BEFORE trigger changes).
-- * For DELETE, the values are those of the deleted row.
-- * Postgres 18+ lets you use OLD. and NEW. aliases to choose which version of the
--   row to read:
--     UPDATE t SET x = 2 WHERE id = 1 RETURNING OLD.x, NEW.x;
--   Older versions have no direct way to get the pre-update value
--   (use a CTE or self-join on a prior SELECT).
-- * Works inside CTEs: WITH moved AS (DELETE ... RETURNING *) INSERT ... SELECT * FROM moved;

pg-easy-94.syntax:
-- General form
SET [ SESSION | LOCAL ] parameter { TO | = } { value | 'value' | DEFAULT };
SET [ SESSION | LOCAL ] TIME ZONE { value | 'value' | LOCAL | DEFAULT };

-- Examples (different parameters from any quiz code)
SET work_mem = '64MB';
SET LOCAL lock_timeout = '2s';

-- Inspect and undo
SHOW work_mem;
SELECT current_setting('work_mem');
RESET work_mem;          -- same as SET work_mem TO DEFAULT

-- Scope notes / gotchas
-- * SESSION is the default keyword when none is written.
-- * SET LOCAL lasts only until the end of the current transaction
--   (COMMIT or ROLLBACK). Outside a transaction block it has no lasting effect.
-- * A plain SET inside a transaction that is later rolled back is undone;
--   if the transaction commits, the value persists for the session.
-- * SET affects only the current connection, not other sessions.
-- * Server-wide defaults: ALTER SYSTEM, postgresql.conf,
--   or ALTER ROLE/DATABASE ... SET (applied to new sessions).
-- * Function-scoped: CREATE FUNCTION ... SET param = value.
-- * set_config('name','value', is_local) is the function form.
-- * Durations accept units such as ms, s, min; a bare number uses the parameter's default unit.
